mapper.select:
SELECT COUNT(*)
  FROM tb_guardian
 WHERE guardian_id = #{value}

SELECT U.user_id AS protected_user_id,
       U.user_name AS protected_user_name
  FROM tb_user U
 WHERE U.user_type = 'PROTECTED'
   AND U.user_name = #{userName}
   AND U.user_id = #{userId}
   AND REPLACE(COALESCE(U.phone_no, ''), '-', '') = #{phoneNo}
 LIMIT 1

SELECT user_id, user_name, user_type
  FROM tb_user
 WHERE user_id = #{value}

SELECT status
  FROM tb_guardian
 WHERE user_id = #{protectedUserId}
   AND guardian_id = #{guardianId}
 LIMIT 1
 FOR UPDATE

mapper.delete:
DELETE FROM tb_guardian
 WHERE guardian_id = #{guardianId}
   AND user_id = #{protectedUserId}
   AND status = 'APPROVED'

DELETE FROM tb_guardian
 WHERE user_id = #{protectedUserId}
   AND guardian_id = #{guardianId}
   AND status = 'APPROVED'

DELETE FROM tb_guardian
 WHERE user_id = #{protectedUserId}
   AND guardian_id = #{guardianId}
   AND status = 'PENDING'

DELETE FROM tb_guardian
	  WHERE user_id = #{userId}
	    AND guardian_id = #{guardianId}
